import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { MaksterEngineeringCompiler } from '../packages/engineering-engine/src/index.js';
import { buildProductionPack } from '../packages/production-pack/src/index.js';
import { buildCommercialPackage } from '../packages/commercial-engine/src/index.js';
import { buildCustomerChangeSummary, compareRevisions, requote } from '../packages/change-intelligence/src/index.js';
import { applyAcceptedChangeOrder, createClientChangeOrder, createCommercialContract, customerSafeChangeOrder, decideClientChangeOrder, issueChangeOrderToken, markInstallmentPaid, productionCommercialGate, rebalancePaymentSchedule, verifyChangeOrderToken, viewClientChangeOrder } from '../packages/client-change-order/src/index.js';
const terms = { clientName: 'Unified Client', validityDays: 14, leadTimeText: '30–45 days', paymentTerms: [{ label: 'Deposit', bps: 5000 }, { label: 'Before delivery', bps: 4000 }, { label: 'After installation', bps: 1000 }], inclusions: ['Furniture'], exclusions: [], notes: [], sellerName: 'Makster Atelier' };
const contractTemplate = [{ id: 'deposit', label: 'Deposit', shareBps: 5000 }, { id: 'production', label: 'Before delivery', shareBps: 4000 }, { id: 'installation', label: 'After installation', shareBps: 1000 }];
function pricing() {
    return { profileId: 'unified-test', name: 'Unified test pricing', currency: 'EUR', materialPrices: [
            { materialSelectionId: '44444444-4444-4444-8444-444444444441', pricingMode: 'per_sheet', thicknessMm: 18, unitCostMinor: 9200, sheetLengthMm: 2800, sheetWidthMm: 2070, wasteBps: 1200 },
            { materialSelectionId: '44444444-4444-4444-8444-444444444441', pricingMode: 'per_sheet', thicknessMm: 16, unitCostMinor: 8200, sheetLengthMm: 2800, sheetWidthMm: 2070, wasteBps: 1200 },
            { materialSelectionId: '44444444-4444-4444-8444-444444444441', pricingMode: 'per_sheet', thicknessMm: 8, unitCostMinor: 4500, sheetLengthMm: 2800, sheetWidthMm: 2070, wasteBps: 1200 },
            { materialSelectionId: '44444444-4444-4444-8444-444444444442', pricingMode: 'per_m2', thicknessMm: 18, unitCostMinor: 11500 },
            { materialSelectionId: '44444444-4444-4444-8444-444444444443', pricingMode: 'per_m2', thicknessMm: 8, unitCostMinor: 1700 },
        ], edgePrices: [{ materialSelectionId: '44444444-4444-4444-8444-444444444444', unitCostPerMeterMinor: 75 }], hardwarePrices: [{ role: 'rail', unitCostMinor: 2400 }, { hardwareSelectionId: '88888888-8888-4888-8888-888888888881', unitCostMinor: 680 }, { hardwareSelectionId: '88888888-8888-4888-8888-888888888882', unitCostMinor: 6200 }, { hardwareSelectionId: '88888888-8888-4888-8888-888888888883', unitCostMinor: 8900 }], labor: [{ id: 'workshop', label: 'Workshop', minutes: 1680, hourlyCostMinor: 2600 }, { id: 'install', label: 'Install', minutes: 600, hourlyCostMinor: 2900, category: 'installation' }], fixedCosts: [{ id: 'transport', label: 'Transport', category: 'transport', costMinor: 12000 }], overheadBps: 800, markupBps: 3500, discountBps: 0, taxBps: 2100, commercialRoundingMinor: 1000 };
}
async function scenario() {
    const before = JSON.parse(await readFile(new URL('file://' + process.cwd() + '/packages/project-model/examples/wardrobe.blum.v1.json'), 'utf8'));
    const after = structuredClone(before);
    after.revision = before.revision + 1;
    after.furniture[0].dimensions.depth.value = 6200;
    const drawer = after.furniture[0].modules[5].contents.find(x => x.kind === 'drawer_stack');
    if (drawer?.kind === 'drawer_stack') {
        drawer.count = 4;
        if (drawer.drawerBox)
            drawer.drawerBox.runnerLinesFromBottom = [{ value: 1300, state: 'confirmed' }, { value: 3000, state: 'confirmed' }, { value: 4700, state: 'confirmed' }, { value: 6400, state: 'confirmed' }];
    }
    const compiler = new MaksterEngineeringCompiler();
    const be = compiler.compile(before), ae = compiler.compile(after);
    assert.equal(be.readyForProduction, true);
    assert.equal(ae.readyForProduction, true);
    const p = pricing();
    const bp = buildProductionPack({ project: before, engineering: be, route: 'manual_workshop', packId: 'bp', generatedAt: '2026-09-04T20:00:00Z' });
    const ap = buildProductionPack({ project: after, engineering: ae, route: 'manual_workshop', packId: 'ap', generatedAt: '2026-09-04T20:01:00Z' });
    const base = buildCommercialPackage({ project: before, engineering: be, productionPack: bp, pricing: p, quoteTerms: terms, quoteId: 'base-q', quoteVersion: 1, estimateId: 'base-e', packageId: 'base-p', generatedAt: '2026-09-04T20:00:00Z' });
    const rq = requote({ basePackage: base, afterProject: after, afterEngineering: ae, productionPack: ap, pricing: p, quoteTerms: terms, quoteId: 'next-q', quoteVersion: 2, packageId: 'next-p', generatedAt: '2026-09-04T20:01:00Z' });
    const next = rq.commercialPackage;
    const report = compareRevisions({ beforeProject: before, afterProject: after, beforeEngineering: be, afterEngineering: ae, beforeQuote: base, afterQuote: next, reportId: 'report-24', generatedAt: '2026-09-04T20:02:00Z' });
    const summary = buildCustomerChangeSummary(report, base, next);
    return { before, after, base, next, report, summary };
}
test('2.4 change intelligence detects CAD dimension and commercial impact', async () => { const s = await scenario(); assert.equal(s.report.status, 'changed'); assert.ok(s.report.projectChanges.some(x => x.category === 'dimensions')); assert.equal(s.report.commercial.available, true); assert.notEqual(s.report.commercial.customerTotalMinor?.delta, 0); });
test('2.4 fixed inputs create deterministic change fingerprint', async () => { const s = await scenario(); const c = new MaksterEngineeringCompiler(); const r = compareRevisions({ beforeProject: s.before, afterProject: s.after, beforeEngineering: c.compile(s.before), afterEngineering: c.compile(s.after), beforeQuote: s.base, afterQuote: s.next, reportId: 'report-24', generatedAt: '2026-09-04T20:02:00Z' }); assert.equal(r.fingerprintSha256, s.report.fingerprintSha256); });
test('2.4 customer change summary contains totals but no cost basis or profit', async () => { const s = await scenario(); const text = JSON.stringify(s.summary); assert.equal(text.includes('costBasis'), false); assert.equal(text.includes('grossProfit'), false); assert.equal(s.summary.newTotalMinor, s.next.quote.totalAmountMinor); });
test('2.4 requote preserves base quote and creates exact newer revision lineage', async () => { const s = await scenario(); assert.equal(s.base.quote.revision, s.before.revision); assert.equal(s.next.quote.revision, s.after.revision); assert.notEqual(s.base.quote.quoteFingerprint, s.next.quote.quoteFingerprint); });
test('2.4 change order binds exact package and report fingerprints', async () => { const s = await scenario(); const o = createClientChangeOrder({ baseQuote: s.base, newQuote: s.next, report: s.report, summary: s.summary, changeOrderId: 'co-24' }); assert.equal(o.binding.baseQuoteFingerprintSha256, s.base.quote.quoteFingerprint); assert.equal(o.binding.newQuoteFingerprintSha256, s.next.quote.quoteFingerprint); assert.equal(o.binding.changeReportFingerprintSha256, s.report.fingerprintSha256); });
test('2.4 approval token is hash-only and customer payload excludes secrets', async () => { const s = await scenario(); const issued = issueChangeOrderToken(createClientChangeOrder({ baseQuote: s.base, newQuote: s.next, report: s.report, summary: s.summary }), '2026-09-04T20:03:00Z'); assert.match(issued.order.approvalTokenHashSha256, /^[0-9a-f]{64}$/); assert.equal(JSON.stringify(issued.order).includes(issued.token), false); verifyChangeOrderToken(issued.order, issued.token, '2026-09-04T20:04:00Z'); assert.throws(() => verifyChangeOrderToken(issued.order, 'bad', '2026-09-04T20:04:00Z'), /change_order_token_invalid/); assert.equal(JSON.stringify(customerSafeChangeOrder(issued.order)).includes('approvalTokenHashSha256'), false); });
test('2.4 commercial contract payment schedule exactly equals agreed total', async () => { const s = await scenario(); const c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate }); assert.equal(c.paymentSchedule.reduce((a, x) => a + x.amountMinor, 0), c.agreedAmountMinor); });
test('2.4 paid installment remains frozen when accepted price changes', async () => { const s = await scenario(); let c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate }); c = markInstallmentPaid(c, c.paymentSchedule[0].installmentId); const paid = c.paymentSchedule[0].amountMinor; const r = rebalancePaymentSchedule(c, s.next.quote.totalAmountMinor); assert.equal(r.paymentSchedule[0].amountMinor, paid); assert.equal(r.paymentSchedule.reduce((a, x) => a + x.amountMinor, 0), s.next.quote.totalAmountMinor); });
test('2.4 production gate blocks uncontracted changed revision', async () => { const s = await scenario(); const c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate }); assert.equal(productionCommercialGate({ projectId: s.before.projectId, revision: s.before.revision, contract: c }).allowed, true); const blocked = productionCommercialGate({ projectId: s.before.projectId, revision: s.after.revision, contract: c }); assert.equal(blocked.allowed, false); assert.equal(blocked.code, 'REVISION_NOT_CURRENTLY_CONTRACTED'); });
test('2.4 accepted change updates contract, creates authorization and opens production gate', async () => { const s = await scenario(); const c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate, contractId: 'c24' }); const issued = issueChangeOrderToken(createClientChangeOrder({ baseQuote: s.base, newQuote: s.next, report: s.report, summary: s.summary })); const viewed = viewClientChangeOrder(issued.order, issued.token); const accepted = decideClientChangeOrder({ order: viewed, token: issued.token, decision: 'accepted', clientName: 'Client' }); const applied = applyAcceptedChangeOrder({ contract: c, order: accepted }); assert.equal(applied.contract.currentRevision, s.after.revision); assert.equal(applied.contract.currentQuoteId, s.next.quote.quoteId); assert.equal(productionCommercialGate({ projectId: s.after.projectId, revision: s.after.revision, contract: applied.contract, authorization: applied.authorization }).allowed, true); });
test('2.4 declined change order cannot mutate contract', async () => { const s = await scenario(); const c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate }); const issued = issueChangeOrderToken(createClientChangeOrder({ baseQuote: s.base, newQuote: s.next, report: s.report, summary: s.summary })); const declined = decideClientChangeOrder({ order: issued.order, token: issued.token, decision: 'declined', clientName: 'Client' }); assert.throws(() => applyAcceptedChangeOrder({ contract: c, order: declined }), /change_order_not_accepted/); });
test('2.4 contract cannot be reduced below money already paid', async () => { const s = await scenario(); let c = createCommercialContract({ projectId: s.before.projectId, quoteId: s.base.quote.quoteId, revision: s.before.revision, currency: 'EUR', agreedAmountMinor: s.base.quote.totalAmountMinor, paymentTemplate: contractTemplate }); c = markInstallmentPaid(c, c.paymentSchedule[0].installmentId); const paid = c.paymentSchedule[0].amountMinor; assert.throws(() => rebalancePaymentSchedule(c, paid - 1), /new_contract_total_below_already_paid/); });
